def _encode_files(files, data):
    """Build the body for a multipart/form-data request.

    Will successfully encode files when passed as a dict or a list of
    tuples. Order is retained if data is a list of tuples but arbitrary
    if parameters are supplied as a dict.
    The tuples may be 2-tuples (filename, fileobj), 3-tuples (filename, fileobj, contentype)
    or 4-tuples (filename, fileobj, contentype, custom_headers).
    """
    if not files:
        raise ValueError("Files must be provided.")
    elif isinstance(data, basestring):
        raise ValueError("Data must not be a string.")

    new_fields = []
    fields = to_key_val_list(data or {})
    files = to_key_val_list(files or {})

    for field, val in fields:
        if isinstance(val, basestring) or not hasattr(val, "__iter__"):
            val = [val]
        for v in val:
            if v is not None:
                # Don't call str() on bytestrings: in Py3 it all goes wrong.
                if not isinstance(v, bytes):
                    v = str(v)

                new_fields.append(
                    (
                        field.decode("utf-8")
                        if isinstance(field, bytes)
                        else field,
                        v.encode("utf-8") if isinstance(v, str) else v,
                    )
                )

    for k, v in files:
        # support for explicit filename
        ft = None
        fh = None
        if isinstance(v, (tuple, list)):
            if len(v) == 2:
                fn, fp = v
            elif len(v) == 3:
                fn, fp, ft = v
            else:
                fn, fp, ft, fh = v
        else:
            fn = guess_filename(v) or k
            fp = v

        if isinstance(fp, (str, bytes, bytearray)):
            fdata = fp
        elif hasattr(fp, "read"):
            fdata = fp.read()
        elif fp is None:
            continue
        else:
            fdata = fp

        rf = RequestField(name=k, data=fdata, filename=fn, headers=fh)
        rf.make_multipart(content_type=ft)
        new_fields.append(rf)

    body, content_type = encode_multipart_formdata(new_fields)

    return body, content_type

if not data and json is not None:
    # urllib3 requires a bytes-like body. Python 2's json.dumps
    # provides this natively, but Python 3 gives a Unicode string.
    content_type = "application/json"

    try:
        body = complexjson.dumps(json, allow_nan=False)
    except ValueError as ve:
        raise InvalidJSONError(ve, request=self)

    if not isinstance(body, bytes):
        body = body.encode("utf-8")

else:
    # Multi-part file uploads.
    if files:
        (body, content_type) = self._encode_files(files, data)
    else:
        if data:
            body = self._encode_params(data)
            if isinstance(data, basestring) or hasattr(data, "read"):
                content_type = None
            else:
                content_type = "application/x-www-form-urlencoded"

    self.prepare_content_length(body)

    # Add content-type if it wasn't explicitly provided.
    if content_type and ("content-type" not in self.headers):
        self.headers["Content-Type"] = content_type

self.body = body

def test_custom_content_type(self, httpbin):
    with open(__file__, "rb") as f1:
        with open(__file__, "rb") as f2:
            data = {"stuff": json.dumps({"a": 123})}
            files = {
                "file1": ("test_requests.py", f1),
                "file2": ("test_requests", f2, "text/py-content-type"),
            }
            r = requests.post(httpbin("post"), data=data, files=files)
    assert r.status_code == 200
    assert b"text/py-content-type" in r.request.body

def _urllib3_request_context(
    request: "PreparedRequest",
    verify: "bool | str | None",
    client_cert: "typing.Tuple[str, str] | str | None",
    poolmanager: "PoolManager",
) -> "(typing.Dict[str, typing.Any], typing.Dict[str, typing.Any])":
    host_params = {}
    pool_kwargs = {}
    parsed_request_url = urlparse(request.url)
    scheme = parsed_request_url.scheme.lower()
    port = parsed_request_url.port

    cert_reqs = "CERT_REQUIRED"
    if verify is False:
        cert_reqs = "CERT_NONE"
    elif isinstance(verify, str):
        if not os.path.isdir(verify):
            pool_kwargs["ca_certs"] = verify
        else:
            pool_kwargs["ca_cert_dir"] = verify
    pool_kwargs["cert_reqs"] = cert_reqs
    if client_cert is not None:
        if isinstance(client_cert, tuple) and len(client_cert) == 2:
            pool_kwargs["cert_file"] = client_cert[0]
            pool_kwargs["key_file"] = client_cert[1]
        else:
            # According to our docs, we allow users to specify just the client
            # cert path
            pool_kwargs["cert_file"] = client_cert
    host_params = {
        "scheme": scheme,
        "host": parsed_request_url.hostname,
        "port": port,
    }
    return host_params, pool_kwargs

def cert_verify(self, conn, url, verify, cert):
    """Verify a SSL certificate. This method should not be called from user
    code, and is only exposed for use when subclassing the
    :class:`HTTPAdapter <requests.adapters.HTTPAdapter>`.

    :param conn: The urllib3 connection object associated with the cert.
    :param url: The requested URL.
    :param verify: Either a boolean, in which case it controls whether we verify
        the server's TLS certificate, or a string, in which case it must be a path
        to a CA bundle to use
    :param cert: The SSL certificate to verify.
    """
    if url.lower().startswith("https") and verify:
        cert_loc = None

        # Allow self-specified cert location.
        if verify is not True:
            cert_loc = verify

        if not cert_loc:
            cert_loc = extract_zipped_paths(DEFAULT_CA_BUNDLE_PATH)

        if not cert_loc or not os.path.exists(cert_loc):
            raise OSError(
                f"Could not find a suitable TLS CA certificate bundle, "
                f"invalid path: {cert_loc}"
            )

        conn.cert_reqs = "CERT_REQUIRED"

        if not os.path.isdir(cert_loc):
            conn.ca_certs = cert_loc
        else:
            conn.ca_cert_dir = cert_loc
    else:
        conn.cert_reqs = "CERT_NONE"
        conn.ca_certs = None
        conn.ca_cert_dir = None

    if cert:
        if not isinstance(cert, basestring):
            conn.cert_file = cert[0]
            conn.key_file = cert[1]
        else:
            conn.cert_file = cert
            conn.key_file = None
        if conn.cert_file and not os.path.exists(conn.cert_file):
            raise OSError(
                f"Could not find the TLS certificate file, "
                f"invalid path: {conn.cert_file}"
            )
        if conn.key_file and not os.path.exists(conn.key_file):
            raise OSError(
                f"Could not find the TLS key file, invalid path: {conn.key_file}"
            )

def test_invalid_ca_certificate_path(self, httpbin_secure):
    INVALID_PATH = "/garbage"
    with pytest.raises(IOError) as e:
        requests.get(httpbin_secure(), verify=INVALID_PATH)
    assert str(
        e.value
    ) == "Could not find a suitable TLS CA certificate bundle, invalid path: {}".format(
        INVALID_PATH
    )

def test_invalid_ssl_certificate_files(self, httpbin_secure):
    INVALID_PATH = "/garbage"
    with pytest.raises(IOError) as e:
        requests.get(httpbin_secure(), cert=INVALID_PATH)
    assert str(
        e.value
    ) == "Could not find the TLS certificate file, invalid path: {}".format(
        INVALID_PATH
    )

    with pytest.raises(IOError) as e:
        requests.get(httpbin_secure(), cert=(".", INVALID_PATH))
    assert str(e.value) == (
        f"Could not find the TLS key file, invalid path: {INVALID_PATH}"
    )

def _find_error_handler(
    self, e: Exception, blueprints: list[str]
) -> ft.ErrorHandlerCallable | None:
    """Return a registered error handler for an exception in this order:
    blueprint handler for a specific code, app handler for a specific code,
    blueprint handler for an exception class, app handler for an exception
    class, or ``None`` if a suitable handler is not found.
    """
    exc_class, code = self._get_exc_class_and_code(type(e))
    names = (*blueprints, None)

    for c in (code, None) if code is not None else (None,):
        for name in names:
            handler_map = self.error_handler_spec[name][c]

            if not handler_map:
                continue

            for cls in exc_class.__mro__:
                handler = handler_map.get(cls)

                if handler is not None:
                    return handler
    return None

